            && spec.Anchor("RearSightAperture", out Vector3 rear) && spec.Anchor("FrontSightTip", out Vector3 front) && (front-rear).sqrMagnitude > .0009f;
        public static float RearDistance(ModelSpec spec) => spec?.Held != null ? spec.Held.RearDistance : spec?.Import != null ? Mathf.Clamp(spec.Import.rearDistance,.08f,.40f) : spec != null && Profiles.TryGetValue(spec.Id, out Entry p) && p.Mode == Route.Iron ? Mathf.Clamp(p.RearDistance,.08f,.40f) : .22f;
        public static float Magnification(ModelSpec spec) => spec?.Held != null ? spec.Held.Magnification : spec?.Import != null ? Mathf.Clamp(spec.Import.magnification,1f,2f) : spec != null && Profiles.TryGetValue(spec.Id, out Entry p) && p.Mode == Route.Iron ? Mathf.Clamp(p.Magnification,1f,2f) : 1.35f;
